// Entity: Customer (becomes a table)
CREATE TABLE customer (
    customer_id BIGSERIAL PRIMARY KEY,  -- Attribute: unique identifier
    name VARCHAR(100) NOT NULL,         -- Attribute: simple data
    email VARCHAR(255) UNIQUE NOT NULL  -- Attribute with constraint
);

// Entity: Order (1:N relationship with Customer)
CREATE TABLE customer_order (
    order_id BIGSERIAL PRIMARY KEY,
    order_date TIMESTAMP NOT NULL,
    customer_id BIGINT NOT NULL,        -- Relationship: FK to Customer
    FOREIGN KEY (customer_id) REFERENCES customer(customer_id)
);

// M:N Relationship: Order ↔ Product requires junction table
CREATE TABLE order_item (
    order_id BIGINT NOT NULL,
    product_id BIGINT NOT NULL,
    quantity INT NOT NULL,              -- Relationship attribute
    PRIMARY KEY (order_id, product_id), -- Composite key
    FOREIGN KEY (order_id) REFERENCES customer_order(order_id),
    FOREIGN KEY (product_id) REFERENCES product(product_id)
);

// 1:1 — Person to Passport (FK on either side, typically optional side)
CREATE TABLE person (
    person_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE TABLE passport (
    passport_id BIGSERIAL PRIMARY KEY,
    passport_number VARCHAR(50) UNIQUE NOT NULL,
    person_id BIGINT UNIQUE NOT NULL,  -- UNIQUE enforces 1:1
    FOREIGN KEY (person_id) REFERENCES person(person_id)
);

// 1:N — Customer to Orders (FK on the N side: order table)
CREATE TABLE customer (
    customer_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE TABLE customer_order (
    order_id BIGSERIAL PRIMARY KEY,
    customer_id BIGINT NOT NULL,       -- FK on the many side
    FOREIGN KEY (customer_id) REFERENCES customer(customer_id)
);

// M:N — Student to Course (requires junction table)
CREATE TABLE enrollment (
    student_id BIGINT NOT NULL,
    course_id BIGINT NOT NULL,
    enrolled_date DATE NOT NULL,
    PRIMARY KEY (student_id, course_id),
    FOREIGN KEY (student_id) REFERENCES student(student_id),
    FOREIGN KEY (course_id) REFERENCES course(course_id)
);

// SQL: Create junction table for Student-Course M:N relationship
CREATE TABLE student (
    student_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE TABLE course (
    course_id BIGSERIAL PRIMARY KEY,
    title VARCHAR(200) NOT NULL
);

CREATE TABLE enrollment (
    student_id BIGINT NOT NULL,
    course_id BIGINT NOT NULL,
    enrolled_date DATE NOT NULL,        // Relationship attribute
    grade CHAR(2),                      // Another relationship attribute
    PRIMARY KEY (student_id, course_id), // Composite key
    FOREIGN KEY (student_id) REFERENCES student(student_id) ON DELETE CASCADE,
    FOREIGN KEY (course_id) REFERENCES course(course_id) ON DELETE CASCADE
);

// JPA Entity: Student side with @ManyToMany
@Entity
public class Student {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long studentId;
    private String name;

    @ManyToMany
    @JoinTable(
        name = "enrollment",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}

// ER Diagram: Customer (1) ←→ (N) Order (M) ←→ (N) Product

// Entity → Table: Customer
CREATE TABLE customer (
    customer_id BIGSERIAL PRIMARY KEY,    // PK chosen
    name VARCHAR(100) NOT NULL,           // Attribute → Column
    email VARCHAR(255) UNIQUE NOT NULL,   // Constraint from ER
    phone VARCHAR(20)
);

// Entity → Table: Product
CREATE TABLE product (
    product_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    price DECIMAL(10,2) NOT NULL CHECK (price >= 0)
);

// Entity → Table: Order (1:N with Customer)
CREATE TABLE customer_order (
    order_id BIGSERIAL PRIMARY KEY,
    order_date TIMESTAMP NOT NULL,
    customer_id BIGINT NOT NULL,          // FK on N side for 1:N
    FOREIGN KEY (customer_id) REFERENCES customer(customer_id)
);

// M:N Relationship → Junction Table: Order ↔ Product
CREATE TABLE order_item (
    order_id BIGINT NOT NULL,             // FK to Order
    product_id BIGINT NOT NULL,           // FK to Product
    quantity INT NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (order_id, product_id),   // Composite PK
    FOREIGN KEY (order_id) REFERENCES customer_order(order_id),
    FOREIGN KEY (product_id) REFERENCES product(product_id)
);

// SQL: Employee table with self-referencing manager_id FK
CREATE TABLE employee (
    employee_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    position VARCHAR(100),
    manager_id BIGINT,                     // Nullable FK to same table
    FOREIGN KEY (manager_id) REFERENCES employee(employee_id)
);

INSERT INTO employee VALUES (1, 'Alice CEO', 'CEO', NULL);  // Root: no manager
INSERT INTO employee VALUES (2, 'Bob CTO', 'CTO', 1);       // Reports to Alice
INSERT INTO employee VALUES (3, 'Carol Dev', 'Developer', 2); // Reports to Bob

// JPA Entity: Self-referencing Employee
@Entity
public class Employee {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long employeeId;
    private String name;
    private String position;

    @ManyToOne
    @JoinColumn(name = "manager_id")      // Nullable by default
    private Employee manager;             // Reference to same entity type

    @OneToMany(mappedBy = "manager")
    private List<Employee> subordinates = new ArrayList<>();
}

// Simple Attribute → Column
CREATE TABLE product (
    product_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(200) NOT NULL,          // Simple attribute
    unit_price DECIMAL(10,2) NOT NULL
);

// Composite Attribute → Multiple Columns
CREATE TABLE customer (
    customer_id BIGSERIAL PRIMARY KEY,
    street VARCHAR(200),                 // Address.street
    city VARCHAR(100),                   // Address.city
    state CHAR(2),                       // Address.state
    zip_code VARCHAR(10)                 // Address.zipCode
);

// Derived Attribute → Computed Column or View
CREATE TABLE person (
    person_id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100),
    birthdate DATE NOT NULL,
    age INT GENERATED ALWAYS AS          // Derived from birthdate
        (EXTRACT(YEAR FROM AGE(CURRENT_DATE, birthdate))) STORED
);

// Multi-Valued Attribute → Separate Table (1:N)
CREATE TABLE customer_phone (
    customer_id BIGINT NOT NULL,
    phone_number VARCHAR(20) NOT NULL,
    phone_type VARCHAR(20),              // home, mobile, work
    PRIMARY KEY (customer_id, phone_number),
    FOREIGN KEY (customer_id) REFERENCES customer(customer_id)
);
